def _key_output(key: Any) -> Any:
    """Render a grouping key for JSON: numeric keys follow projection rules."""
    if isinstance(key, Decimal):
        return _number(key)
    return key


def _aggregate_result(query: Query, count: int, sums: Dict[str, Decimal]) -> Dict[str, Any]:
    row: List[Any] = []
    for item in query.select:
        if item.kind == "count_star":
            row.append(count)
        else:
            row.append(_number(sums[item.column]))
    return {
        "columns": [item.text for item in query.select],
        "rows": [row],
        "row_count": 1,
    }


def _grouped_result(
    query: Query,
    order: List[Tuple[Any, ...]],
    counts: Dict[Tuple[Any, ...], int],
    sums: Dict[Tuple[Any, ...], Dict[str, Decimal]],
) -> Dict[str, Any]:
    group_cols = query.group_by
    rows: List[List[Any]] = []
    for key in order:
        row: List[Any] = []
        for pos, item in enumerate(query.select):
            if pos < len(group_cols):
                # The leading SELECT items are the GROUP BY columns, in order.
                row.append(_key_output(key[pos]))
            elif item.kind == "count_star":
                row.append(counts[key])
            else:
                row.append(_number(sums[key][item.column]))
        rows.append(row)
    return {
        "columns": [item.text for item in query.select],
        "rows": rows,
        "row_count": len(rows),
    }


def _sortable(value: Any):
    """Map one rendered result cell to a comparison value.

    Integers and exact :class:`Decimal` values sort numerically (so
    ``1`` and ``1.0`` tie); every other value — including the empty
    field and text that is not a finite decimal — sorts by its raw
    string text, never by a forced numeric conversion.
    """
    if isinstance(value, Decimal):
        return value
    if isinstance(value, int) and not isinstance(value, bool):
        return Decimal(value)
    return value


def _compare_sort_value(left: Any, right: Any) -> int:
    left_key = _sortable(left)
    right_key = _sortable(right)
    if isinstance(left_key, Decimal) and isinstance(right_key, Decimal):
        # Exact finite decimal comparison: 1 and 1.0 are equivalent.
        if left_key == right_key:
            return 0
        return -1 if left_key < right_key else 1

